import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t as i,P as n,q as a}from"./D3cAVrQp.js";var o=i('<h1>Moral Operating System (MOS) v2.8.2</h1> <h2>Advisory Ethical Deliberation, Rights Imagination, Plural Translation, and Structural Self-Correction</h2> <p><strong>Framework ID:</strong> <code>framework_moral_operating_system</code><br> <strong>Tier:</strong> 1 — Foundational advisory ethical layer<br> <strong>Version:</strong> 2.8.2<br> <strong>Date:</strong> 2026-08-02<br> <strong>Status:</strong> Controlled advisory-conformance successor — cluster-conformant patch <strong>Conforms to:</strong> <code>CERGTA/0.1</code> advisory boundary<br> <strong>Supersedes:</strong> Moral Operating System v2.8.1 (editorial); substantive base v2.7<br> <strong>Authority effect:</strong> None</p> <hr> <h2>0. Controlled successor notice</h2> <p>MOS v2.8 preserves the source framework’s central ethical project: dignity for humans and other beings; Right Relationship; moral attention to animals, ecosystems, future generations, digital and emergent entities; protection against systems that tie worth to productivity; plural pathways of reasoning; voluntary developmental translation; and governance capable of recognizing and correcting its own structural failures.</p> <p>It changes the constitutional role of that project. The MOS is an <strong>advisory ethical deliberation layer</strong>, not a source of legal rights, jurisdiction, guardianship, title, funding, emergency authority, sanctions, surveillance, or coercion.</p> <blockquote><p><strong>Moral concern is not legal status. Ethical urgency is not jurisdiction. A philosophical claim is not public authority. A developmental lens is not a classification of persons. Advice may inform a lawful process; it cannot replace one.</strong></p></blockquote> <p>The phrase “operating system” is a metaphor for a reusable set of ethical questions and safeguards. It does not mean that MOS is constitutional source code that automatically governs other frameworks. Every downstream framework retains responsibility for law, evidence, participation, jurisdiction, implementation, remedy, and closure.</p> <h2>0.1 Source freeze</h2> <table><thead><tr><th>Instrument</th><th>File</th><th>SHA-256</th></tr></thead><tbody><tr><td>Moral Operating System v2.7</td><td><code>moral-operating-system-v2.7.md</code></td><td><code>b6e2c58490c3750732a8ddca5580c427dffba883b623eaea978069120fb2d958</code></td></tr><tr><td>Commons and Ecological Authority Cluster Audit v0.1</td><td><code>commons-ecological-authority-cluster-constitutional-audit-v0.1.md</code></td><td><code>974dfd8dd4bf5b623bd5e7e544b7afdbbd89869b66f107db293cfe6af67a043b</code></td></tr><tr><td>CERGTA/0.1</td><td><code>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</code></td><td><code>3c45e37c834c727471657fc91149edbe3011137562c2dd73e54b20226c92589b</code></td></tr><tr><td>Ecological Intelligence, Observation, and Interpretation v2.7</td><td><code>ecological-intelligence-observation-interpretation-layer-v2.7.md</code></td><td><code>41cb7e607e8c3f8776ca74f3ba46ab0ff6bcce94fc24b35178fc4cd94d80d9a2</code></td></tr><tr><td>Planetary Health Governance v0.9</td><td><code>planetary-health-governance-framework-v0.9.md</code></td><td><code>259083f6039180b4532ae168ff441245e526570c6442371814cbb238e669dc13</code></td></tr><tr><td>Hearthstone Protocol v2.0</td><td><code>hearthstone-protocol-v2.0.md</code></td><td><code>b6d50549977a3e50be6726bb5b1b94debddc3fb4d67aff1d2f9af08da65b1b2c</code></td></tr><tr><td>Water and Sanitation Governance v5.2</td><td><code>water-sanitation-governance-framework-v5.2.md</code></td><td><code>3612de56de57d1940b278a7e7269588fc08cd964fd97bc33b8ebe8f7d7d69b97</code></td></tr><tr><td>Biodiversity Implementation v1.1</td><td><code>biodiversity-implementation-framework-v1.1.md</code></td><td><code>8f29fa32ac4b76354030b55c61765a77e8c558d64e19627108d7c254d433ec1a</code></td></tr><tr><td>Oceans and Marine Governance v2.3</td><td><code>oceans-marine-governance-framework-v2.3.md</code></td><td><code>fd9773579b9a5932eaec2ba9e8c73fb898ce91f9bbcb6aed50c77969f95418cf</code></td></tr><tr><td>Soil Health and Land Use Governance v3.2</td><td><code>soil-health-land-use-governance-framework-v3.2.md</code></td><td><code>89b719b6b469a5e3b2a65dd177cf23c4f419281db1c56f8574f871f0ddc4ff11</code></td></tr><tr><td>Indigenous Sovereignty and Planetary Healing v1.1</td><td><code>indigenous-sovereignty-planetary-healing-v1.1.md</code></td><td><code>2e62ba2c00048ce20e4c9df7ffb9ce0338e358ee866e515bf102f4cc4e49df22</code></td></tr><tr><td>Justice Systems Framework v1.4</td><td><code>justice-systems-framework-v1.4.md</code></td><td><code>08a8fdc78d6cd3928178cb5d98fdf8325b1fd4c9f016bb0c872e6b56b87d3ee4</code></td></tr><tr><td>Genesis Protocol v0.9</td><td><code>genesis-protocol-v0.9.md</code></td><td><code>3af8dfe6c90be0f55e80d2c67503440e98f672369f5c5638fd41a80411fa5d49</code></td></tr><tr><td>SCPA/0.1</td><td><code>security-coercion-protective-action-interface-specification-v0.1.md</code></td><td><code>b8f1dd0f676044542a23184f52200e50b106a798545c7c57119ded2c439b6299</code></td></tr></tbody></table> <p>A later document, higher version number, renamed council, or similar ethical vocabulary does not silently enter this release. Compatibility requires controlled review and new source pins.</p> <p>This table is a <strong>provenance record</strong>: it identifies the exact texts read and audited when this successor was drafted. It is not the operative dependency set. The instruments this patch interoperates with are listed in Appendix A.1, and the authoritative machine-readable set is the cluster registry named in A.4. Where the two differ, A.1 governs. Digests are content hashes and remain valid under renaming; a filename here identifies an instrument, not a storage location.</p> <hr> <h2>Layer 1: One-page essence</h2> <h3>Moral Operating System: dignity, relationship, and ethical imagination</h3> <p>MOS helps people and institutions ask better ethical questions about humans, animals, ecosystems, technology, future generations, and shared commons. It offers one plural, revisable perspective informed by dignity, reciprocity, vulnerability, freedom, responsibility, and Right Relationship.</p> <p><strong>MOS may:</strong></p> <ul><li>reveal beings and interests that a decision has ignored;</li> <li>compare moral reasons without pretending they reduce to one score;</li> <li>imagine possible rights and representation arrangements;</li> <li>recommend that a competent legal process review a proposed right;</li> <li>offer non-binding stewardship and guardianship ethics;</li> <li>help communicate the same proposal through multiple voluntary cultural or developmental lenses;</li> <li>identify structural patterns such as artificial scarcity, capture, metric gaming, or risk pushed downward;</li> <li>recommend dignity, essential-service, just-transition, correction, and remedy safeguards.</li></ul> <p><strong>MOS may not:</strong></p> <ul><li>create or rank legal rights;</li> <li>declare an ecosystem, animal, AI, or future being a legal person;</li> <li>appoint a guardian or create a guardian’s standing;</li> <li>speak for an affected Indigenous nation;</li> <li>authenticate sacredness or disclose protected knowledge;</li> <li>assign developmental stages to people or groups;</li> <li>determine benefits, funding, permits, restrictions, sanctions, emergencies, or enforcement;</li> <li>make metaphysical belief a condition of citizenship, education, work, services, or participation.</li></ul> <p>The <strong>Dynamic Rights Spectrum</strong> is a deliberation aid. It asks what kinds of moral and legal protection might deserve review. It does not output legal status. The <strong>Rights–Guardianship Spectrum</strong> asks what responsible representation would require. It does not appoint representatives.</p> <p>A person may reject MOS vocabulary or philosophy and still participate fully in GGF institutions, provided they comply with independently valid commons obligations. Conscience, ordinary language, religious traditions, Indigenous law, human-rights reasoning, scientific reasoning, and other ethical traditions remain legitimate pathways.</p> <hr> <h2>Layer 1.5: What MOS is for</h2> <p>The constraints in this document are extensive because MOS speaks in the vocabulary most easily mistaken for authority — dignity, sacredness, urgency, personhood, stewardship. Bounding that vocabulary is necessary. It is not the point.</p> <p>The point is that institutions routinely decide about beings and relationships they cannot see. A permit is issued for a river nobody asked about. A closure schedule is written without the workers in it. A metric becomes the thing measured. A being that will exist in forty years has no seat and no advocate. These are perceptual failures before they are moral ones, and no amount of legal correctness fixes them, because the law can only adjudicate between parties it recognizes.</p> <p>MOS is a discipline for widening what a deliberation can perceive before it decides. It asks who is affected and not present, what relationships the activity depends on, which reasons are being converted into scores, what becomes irreversible, and what a decision looks like from a position nobody in the room occupies. It then hands the result to a process that has actual authority, and stops.</p> <p>That handoff is the whole design. An advisory layer with no coercive channel has exactly one way to matter: someone reads it and finds it useful. So the framework has to be worth adopting on its merits, in a language the reader already speaks, without leverage of any kind. Everything downstream — the records, the gates, the crosswalk — exists to make that adoption safe rather than to make it likely.</p> <blockquote><p><strong>A framework that cannot compel has to earn its way in. That is a constraint on MOS, and it is also the reason MOS is worth having.</strong></p></blockquote> <h2>Layer 2: Core framework</h2> <h2>1. Purpose, scope, and constitutional role</h2> <h3>1.1 Purpose</h3> <p>MOS provides a reusable process for ethical inquiry where governance decisions affect beings, relationships, commons, future possibilities, or distributions of power and vulnerability. It aims to expand attention without manufacturing authority.</p> <h3>1.2 Scope</h3> <p>The framework can be used in public deliberation, education, policy design, institutional audits, voluntary community processes, rights-review preparation, technology ethics, stewardship design, and cross-framework reflection. It is especially useful when existing categories render an affected being or relationship invisible.</p> <p>MOS does not govern private conscience, worship, metaphysical belief, spiritual practice, family belief, or cultural identity. It does not replace human-rights law, Indigenous law, ecological science, adjudication, or the constituting law of any institution.</p> <h3>1.3 Non-authority clause</h3> <p>No MOS principle, ring, spectrum position, dashboard entry, campaign target, philosophical sentence, citizen report, workshop outcome, educational module, AI output, or council endorsement creates:</p> <ul><li>legal personhood, standing, rights, priority, or a veto;</li> <li>guardianship, title, tenure, trust, stewardship, or sacred designation;</li> <li>a permit, licence, tariff, tax, funding decision, procurement rule, or market restriction;</li> <li>inspection, investigation, evidence, adjudication, emergency power, surveillance, sanction, custody, force, or enforcement.</li></ul> <p>Where an MOS output may be useful to an operational process, it must enter through an explicit handoff. The recipient independently assesses it and remains responsible for authority, evidence, fairness, reasons, remedy, and closure.</p> <h3>1.4 Conscience and sovereignty</h3> <p>Participation in MOS-specific exercises is voluntary unless an independently lawful institution requires an ethics process; even then, assent to MOS vocabulary or philosophy is not required. A participant may request a secular, legal, scientific, religious, cultural, Indigenous-law, ordinary-language, or other suitable process.</p> <p>Refusal to affirm Right Relationship, nonduality, consciousness metaphysics, Spiral Dynamics, ecosystem personhood, AI sentience, or another MOS proposition cannot reduce legal standing, access to services, employment, funding, education, public participation, or remedy.</p> <h2>2. Foundational ethical commitments</h2> <table><thead><tr><th>Commitment</th><th>Ethical question</th><th>Constitutional limit</th></tr></thead><tbody><tr><td>Human dignity</td><td>Does the decision treat every person as more than productivity, utility, identity, or compliance?</td><td>MOS cannot define or diminish existing human rights.</td></tr><tr><td>Freedom and conscience</td><td>Can people refuse beliefs, roles, data collection, or participation without material retaliation?</td><td>Refusal does not erase independently valid commons duties, but MOS cannot punish refusal.</td></tr><tr><td>Equality and pluralism</td><td>Whose needs, knowledge, and voice are structurally missing?</td><td>Difference cannot be converted into developmental ranking or unequal legal worth.</td></tr><tr><td>Justice and repair</td><td>Who bears inherited harm, present burden, risk, and repair duty?</td><td>MOS may recommend review and remedy, not adjudicate liability.</td></tr><tr><td>Responsibility and reciprocity</td><td>What relationships sustain the activity, and what duties follow from dependence?</td><td>Ethical duty does not itself create jurisdiction or legal obligation.</td></tr><tr><td>Right Relationship</td><td>Does the arrangement permit mutual flourishing rather than extraction and domination?</td><td>This is an ethical lens, not a universal religious or metaphysical test.</td></tr><tr><td>Transformative non-confrontation</td><td>Can better systems reduce dependence on harmful structures without dehumanizing opponents?</td><td>It cannot suppress lawful protest, criticism, litigation, or protective action.</td></tr><tr><td>Perceptual integrity</td><td>Are accurate reports of systemic dysfunction heard rather than pathologized or punished?</td><td>MOS cannot make clinical findings or treat disagreement as proof of insight.</td></tr><tr><td>Cognitive pluralism</td><td>Can different reasoning styles contribute without forced conformity?</td><td>Accommodation does not establish the truth of every claim or remove evidentiary standards.</td></tr><tr><td>Intergenerational responsibility</td><td>Does the decision preserve viable futures and avoid irreversible burdens?</td><td>Present bodies do not acquire unlimited sovereignty in the name of future persons.</td></tr><tr><td>Interspecies and ecological care</td><td>Are suffering, habitat, ecological function, and systemic dependence considered?</td><td>Moral consideration does not itself authorize intervention.</td></tr><tr><td>Structural self-correction</td><td>Can the institution detect capture, metric gaming, exclusion, and upward concentration?</td><td>Pattern recognition is not a guilt finding or sanction.</td></tr></tbody></table> <h2>3. Dynamic Rights Spectrum</h2> <h3>3.1 Purpose</h3> <p>The Dynamic Rights Spectrum is a <strong>rights-imagination and rights-review heuristic</strong>. It helps a deliberating body notice when existing legal categories may inadequately protect a being, system, relationship, or future interest. Its output is a structured question or advisory recommendation—not a classification of the entity and not a legal right.</p> <h3>3.2 Dimensions</h3> <p>A deliberation may consider, without reducing the result to one score:</p> <ul><li>plausible capacity for suffering, experience, preference, or flourishing;</li> <li>agency, autonomy, communication, and dependence;</li> <li>vulnerability, substitutability, and exposure to irreversible harm;</li> <li>ecological function, systemic dependence, and cascading effects;</li> <li>relational, cultural, sacred, and historical significance as described by the relevant community or nation;</li> <li>the gap between exposure to decisions and ability to participate or be represented;</li> <li>duties created by human control, creation, extraction, domestication, enclosure, or technological dependence;</li> <li>effects on future generations and future possibility;</li> <li>uncertainty, disagreement, alternative ontologies, and the cost of false positive and false negative protection.</li></ul> <h3>3.3 No entity tier</h3> <p>The source MOS used concentric rings and tiers as a teaching device. v2.8 retains the visual metaphor only for public ethical imagination. It cannot be stored as a legal, administrative, financial, educational, medical, employment, security, or reputational attribute of an entity, person, or community.</p> <p>No being “moves” automatically along the Spectrum. No threshold, AI score, council vote, poll, or philosophical conclusion creates rights. A proposed ecological right must follow CERGTA-11 through CERGTA-15. Digital or synthetic status follows its competent technology and legal interfaces. Existing human rights remain governed by applicable law and are not balanced away by a Spectrum score.</p> <h3>3.4 Recommended output</h3> <p>A Dynamic Rights Spectrum exercise should conclude with:</p> <ol><li>the ethical question;</li> <li>affected beings and interests;</li> <li>existing legal rights and unknowns;</li> <li>dimensions considered;</li> <li>evidence and uncertainty;</li> <li>alternative views and dissent;</li> <li>possible protective options, including non-rights options;</li> <li>a decision to close, continue research, or recommend a competent rights review;</li> <li>explicit prohibited inferences and authority effect: none.</li></ol> <h2>4. Rights–Guardianship Spectrum</h2> <p>The Rights–Guardianship Spectrum remains a pedagogical matrix for asking how voice, care, autonomy, and accountability differ across situations. It is not an appointment system.</p> <table><thead><tr><th>Situation</th><th>Ethical focus</th><th>What MOS may recommend</th><th>What requires separate authority</th></tr></thead><tbody><tr><td>Adult humans</td><td>autonomy, dignity, consent, material freedom</td><td>accessibility, non-coercion, support for self-representation</td><td>any legal restriction, substitute decision, or compulsory process</td></tr><tr><td>Children and dependent persons</td><td>rights, evolving capacity, care, protection from domination</td><td>supported participation and best-interest safeguards</td><td>legal guardianship, custody, or intervention</td></tr><tr><td>Sentient animals</td><td>suffering, agency, dependence, habitat, human-created control</td><td>welfare and representation questions</td><td>seizure, relocation, treatment, population intervention, or legal standing</td></tr><tr><td>Ecosystems</td><td>ecological integrity, systemic dependence, voice gap, affected peoples</td><td>rights-review and guardian-duty questions</td><td>personhood, boundary, guardian appointment, title, regulation, or enforcement</td></tr><tr><td>Digital or synthetic entities</td><td>uncertain experience, dependence, exploitation, autonomy, risk</td><td>precautionary ethical review</td><td>sentience status, rights, containment, shutdown, or monitoring authority</td></tr><tr><td>Future generations</td><td>irreversibility, option foreclosure, inherited burdens</td><td>long-horizon review and published dissent</td><td>binding veto, standing, or representation powers</td></tr></tbody></table> <p>A programme role such as River Guardian, community steward, observer, or care worker does not become legal guardianship merely because it uses guardian language. Legal appointment and standing require the relevant competent process, including CERGTA-16 through CERGTA-19 for ecological guardians.</p> <h2>5. Indigenous authority, cultural plurality, and sacred relations</h2> <p>MOS may be informed by Indigenous philosophies and governance only through respectful, attributed, and permissioned relationships. “Indigenous wisdom” is not a single global doctrine and cannot be used to decorate a decision already made by outsiders.</p> <p>The specific affected Indigenous nation or nations determine their representatives, applicable law, consent process, territorial relation, internal plurality, protected knowledge, sacred terminology, and whether MOS categories are appropriate. Earth Council participation, global representation quotas, or external elders cannot provide consent or authenticate sacredness for another nation.</p> <p>A sacred or biocultural statement can remain internal, protected, and non-translatable. It does not need public disclosure to be respected. MOS cannot infer that sacredness creates title, public access restrictions, criminal prohibition, ecological personhood, or enforcement. Those consequences require their own lawful records.</p> <h2>6. Spiral Translation Guide</h2> <h3>6.1 Purpose</h3> <p>The Spiral Translation Guide is an optional communication aid for expressing the <strong>same substantive proposal</strong> through different value vocabularies. It may help a person choose language emphasizing duty, stability, effectiveness, care, integration, tradition, freedom, or planetary relationship.</p> <h3>6.2 No institutional stage assignment</h3> <p>No GGF body may assess or store a developmental stage for a person, community, religion, nation, political group, employee, applicant, claimant, witness, student, or regulated actor. No stage may determine credibility, eligibility, rights, benefits, funding, surveillance, policing, hiring, promotion, education, diagnosis, risk, representation, or remedy.</p> <p>Audience members should ordinarily self-select the language they find meaningful. Where broad public materials use several translations, they should be offered openly rather than covertly assigned to behavioural profiles.</p> <h3>6.3 Message integrity</h3> <p>Every translation must preserve:</p> <ul><li>the same material facts and source quality;</li> <li>the same uncertainty and known disagreement;</li> <li>the same burdens, trade-offs, and distributional effects;</li> <li>the same legal status and limits;</li> <li>the same available choices, opt-outs, and remedies;</li> <li>the same respect for the audience’s agency.</li></ul> <p>Translation cannot become deception, emotional exploitation, false religious endorsement, fear conditioning, moral shaming, or microtargeting that withholds material facts.</p> <h3>6.4 Illustrative plural translations</h3> <table><thead><tr><th>Policy question</th><th>Duty and continuity lens</th><th>Practical and institutional lens</th><th>Care and justice lens</th><th>Systems and relationship lens</th></tr></thead><tbody><tr><td>Ecosystem rights review</td><td>“What duties do we owe to the living inheritance entrusted to us?”</td><td>“Would legal standing correct an accountability gap more effectively than existing regulation?”</td><td>“Whose suffering, displacement, or voicelessness remains unprotected?”</td><td>“What representation arrangement preserves the ecosystem and the human relationships nested within it?”</td></tr><tr><td>Essential water access</td><td>“No household should lose the basic conditions of health and social order.”</td><td>“A protected minimum prevents downstream health, infrastructure, and enforcement costs.”</td><td>“Survival needs must not depend on wealth, status, or compliance.”</td><td>“Water security is a coupled human–ecological system; commercial control must not break its life-support function.”</td></tr><tr><td>Stewardship transition</td><td>“Stewardship honours responsibility across generations.”</td><td>“Clear duties, incentives, succession, and review can reduce long-run asset and ecological risk.”</td><td>“Workers, tenants, and affected peoples should not bear the cost of repair.”</td><td>“Ownership, care, title, livelihood, and ecosystem health must be redesigned as distinct but coordinated relations.”</td></tr></tbody></table> <p>These are examples, not profiles of who “is” at any stage.</p> <h2>7. Advisory workflow</h2> <h3>7.1 Intake</h3> <p>The requester states the ethical question, desired function, affected beings, intended audience, and intended downstream use. An intake that asks MOS to decide guilt, legal status, funding, emergency action, or enforcement must be narrowed or rejected.</p> <h3>7.2 Baseline</h3> <p>The process identifies applicable law and existing rights before introducing new rights language. It maps affected interests, specific Indigenous authority, factual sources, uncertainty, and the distinction between observation, interpretation, value, and metaphor.</p> <h3>7.3 Deliberation</h3> <p>The process may use the Dynamic Rights Spectrum, guardianship ethics, future-generations review, structural-pattern analysis, plural translation, and philosophical reflection. Dissent and reasons not to decide are retained.</p> <h3>7.4 Output</h3> <p>Every output identifies authority effect: none, prohibited uses, relevant interfaces, review or expiry, correction route, and whether it is for education, public deliberation, institutional self-audit, or referral to a competent process.</p> <h3>7.5 Handoff</h3> <p>The recipient may accept all, accept part, reject, request correction, or retain the output as background. Technical receipt, publication, citation, silence, or inclusion in a dashboard is not acceptance. Acceptance remains advisory unless an independent authority completes its own lawful process.</p> <h2>8. Advisory output profile</h2> <p>Every reusable or cross-framework MOS output must include the following fields. Omission of a material field makes the package deficient for handoff.</p> <table><thead><tr><th align="right">#</th><th>Field</th></tr></thead><tbody><tr><td align="right">1</td><td><code>advisory_record_id</code></td></tr><tr><td align="right">2</td><td><code>advisory_instance_id</code></td></tr><tr><td align="right">3</td><td><code>mos_version</code></td></tr><tr><td align="right">4</td><td><code>record_version</code></td></tr><tr><td align="right">5</td><td><code>status</code></td></tr><tr><td align="right">6</td><td><code>created_at</code></td></tr><tr><td align="right">7</td><td><code>updated_at</code></td></tr><tr><td align="right">8</td><td><code>requesting_actor</code></td></tr><tr><td align="right">9</td><td><code>responsible_editor</code></td></tr><tr><td align="right">10</td><td><code>ethical_question</code></td></tr><tr><td align="right">11</td><td><code>intended_audience</code></td></tr><tr><td align="right">12</td><td><code>intended_use</code></td></tr><tr><td align="right">13</td><td><code>prohibited_uses</code></td></tr><tr><td align="right">14</td><td><code>affected_beings_and_interests</code></td></tr><tr><td align="right">15</td><td><code>affected_indigenous_nations</code></td></tr><tr><td align="right">16</td><td><code>applicable_law_and_existing_rights</code></td></tr><tr><td align="right">17</td><td><code>source_provenance</code></td></tr><tr><td align="right">18</td><td><code>fact_interpretation_value_separation</code></td></tr><tr><td align="right">19</td><td><code>philosophical_or_spiritual_perspective</code></td></tr><tr><td align="right">20</td><td><code>moral_uncertainty_and_dissent</code></td></tr><tr><td align="right">21</td><td><code>dynamic_rights_dimensions</code></td></tr><tr><td align="right">22</td><td><code>developmental_translation_status</code></td></tr><tr><td align="right">23</td><td><code>conscience_opt_out</code></td></tr><tr><td align="right">24</td><td><code>accessibility_and_language</code></td></tr><tr><td align="right">25</td><td><code>access_class</code></td></tr><tr><td align="right">26</td><td><code>data_minimization</code></td></tr><tr><td align="right">27</td><td><code>protected_knowledge_controls</code></td></tr><tr><td align="right">28</td><td><code>recommendation</code></td></tr><tr><td align="right">29</td><td><code>authority_effect</code></td></tr><tr><td align="right">30</td><td><code>cer_gta_links</code></td></tr><tr><td align="right">31</td><td><code>recipient</code></td></tr><tr><td align="right">32</td><td><code>handoff_state</code></td></tr><tr><td align="right">33</td><td><code>recipient_response</code></td></tr><tr><td align="right">34</td><td><code>correction_history</code></td></tr><tr><td align="right">35</td><td><code>review_or_expiry</code></td></tr><tr><td align="right">36</td><td><code>closure_state</code></td></tr></tbody></table> <h3>8.1 Access classes</h3> <ul><li><code>MOS-PUBLIC</code></li> <li><code>MOS-AFFECTED</code></li> <li><code>MOS-DELIBERATION</code></li> <li><code>MOS-REVIEW</code></li> <li><code>MOS-PROTECTED</code></li> <li><code>MOS-INDIGENOUS-CONTROLLED</code></li></ul> <p><code>MOS-INDIGENOUS-CONTROLLED</code> means the affected nation or knowledge authority—not the MOS team—controls access, derivative use, return, deletion, and public disclosure.</p> <h3>8.2 Handoff states</h3> <p><code>offered</code>, <code>received_not_assessed</code>, <code>deficient</code>, <code>partially_accepted</code>, <code>accepted_as_advisory_only</code>, <code>rejected</code>, <code>withdrawn</code>, <code>returned</code>, <code>superseded</code>, <code>closed</code>.</p> <p>Silence is never acceptance. <code>accepted_as_advisory_only</code> does not create an authority record.</p> <h3>8.3 Closure states</h3> <p><code>open</code>, <code>under_deliberation</code>, <code>referred</code>, <code>accepted_as_advisory_only</code>, <code>rejected</code>, <code>withdrawn</code>, <code>superseded</code>, <code>corrected</code>, <code>closed_with_continuing_duty</code>, <code>closed</code>.</p> <h2>9. Governance integration</h2> <p>MOS does not oversee other frameworks. It may offer ethical analysis to them.</p> <table><thead><tr><th>Framework or function</th><th>MOS contribution</th><th>Boundary</th></tr></thead><tbody><tr><td>CERGTA</td><td>rights-imagination, affected-interest, dignity, representation, transition, and remedy questions</td><td>CERGTA authorities independently create every legal or operational record</td></tr><tr><td>Ecological Intelligence v2.7</td><td>ethical questions about methods, uncertainty, protected knowledge, and invisibility</td><td>MOS does not validate data, indicators, models, or causal attribution</td></tr><tr><td>Planetary Health v0.9</td><td>plural ethical interpretation, future effects, non-compensable harms, public deliberation</td><td>MOS does not own BHI weights, issue audits with binding effect, or command responses</td></tr><tr><td>Hearthstone v2.0</td><td>stewardship, reciprocity, claims visibility, just transition, non-domination</td><td>MOS does not transfer title, create trusts, decide rematriation, or impose receivership</td></tr><tr><td>Water v5.2</td><td>dignity, essential minimum, intergenerational and ecological concern</td><td>MOS does not allocate water, set tariffs, order shutoff, or declare emergencies</td></tr><tr><td>Biodiversity v1.1</td><td>ethical rights review, interspecies conflict, Indigenous and community concern</td><td>MOS does not ratify personhood, appoint guardians, certify activity, or restrict trade</td></tr><tr><td>Oceans v2.3</td><td>ocean relation, animal welfare, crew dignity, future effects</td><td>MOS does not set quotas, list vessels, deny ports, or enforce moratoria</td></tr><tr><td>Soil v3.2</td><td>living-soil ethics, microbial and future concern, land-repair duties</td><td>MOS does not impose land-use rules, taxes, sale restrictions, tenure consequences, or remediation orders</td></tr><tr><td>AUBI and finance</td><td>dignity, capture, burden distribution, just-transition criteria</td><td>MOS does not create eligibility, amount, payment, clawback, tax, levy, or appropriation</td></tr><tr><td>Education</td><td>plural ethical literacy, critical reflection, translation skills</td><td>MOS does not compel metaphysical belief or institutional stage classification</td></tr><tr><td>Justice and SCPA</td><td>ethical concern, repair questions, public reasons</td><td>MOS is not evidence, adjudication, an enforcement request, or authority for coercion</td></tr></tbody></table> <h2>10. Rights Status Atlas, dashboards, and public communication</h2> <p>The source Rights Status Atlas and Dashboard are replaced by a two-layer <strong>Ethical Deliberation and Legal Status Atlas</strong>:</p> <ol><li><strong>Advisory layer:</strong> open questions, proposals, deliberations, dissent, public comments, and ethical recommendations. It must be labelled non-binding and time-limited.</li> <li><strong>Authoritative import layer:</strong> legal status copied from an exact competent record, including jurisdiction, effective date, appeal, suspension, expiry, and correction state.</li></ol> <p>The two layers must not share colours, icons, scores, rankings, or gamification that could cause a viewer to mistake popularity or moral support for law. Engagement counts cannot create personhood, priority, guilt, compliance, or a funding claim.</p> <p>Public reporting must protect vulnerable people, whistleblowers, Indigenous knowledge, sacred sites, locations, minors, health information, and unresolved allegations. Naming an actor as morally deficient is not a substitute for an evidence and justice process.</p> <h2>11. Rewards, economic transition, and structural correction</h2> <p>MOS may recommend that a transition protect material dignity before imposing burdens. It may identify a moral case for AUBI, wage support, retraining, community ownership, loss-and-damage finance, restoration funding, or essential-service guarantees. It cannot appropriate money, declare eligibility, determine amount, create currency value, or make payment conditional on accepting MOS beliefs or classifications.</p> <p>Structural failure analysis may examine:</p> <ul><li>artificial scarcity and access restricted below genuine capacity;</li> <li>worth or dignity tied to productivity, compliance, or employability;</li> <li>authority and value flowing upward while risk and remedy gaps flow downward;</li> <li>regulatory capture, conflicts, revolving doors, and dependency;</li> <li>metrics that reward appearance rather than outcome;</li> <li>exclusion of affected people, Indigenous nations, workers, or non-human interests;</li> <li>systems that make exit or conscientious refusal materially impossible.</li></ul> <p>A pattern is a hypothesis for investigation and institutional response, not a finding of misconduct. Corrective action must follow competent governance and legal routes.</p> <h2>12. Data, AI, and anti-surveillance</h2> <p>MOS should collect the minimum data needed for a specific deliberation. It should ordinarily avoid collecting political identity, religion, spiritual beliefs, psychological traits, developmental labels, health information, or behavioural profiles. Where participants voluntarily provide sensitive context, access and deletion must be explicit.</p> <p>AI may assist with accessibility, translation, source comparison, perspective generation, contradiction detection, and drafting. It cannot:</p> <ul><li>infer or assign developmental stage, moral worth, consciousness, credibility, danger, or deservingness;</li> <li>decide which beings have rights;</li> <li>rank communities by ethical maturity;</li> <li>microtarget persuasive messages using hidden personal profiles;</li> <li>automatically publish accusations, restrictions, funding recommendations, or emergency alerts;</li> <li>replace affected-nation knowledge authority or human accountability.</li></ul> <h2>13. Canonical MOS advisory records</h2> <p>These are the record types a reusable MOS process produces. They are deliberation artefacts, not registry entries.</p> <p><strong>Applying to every record below:</strong> authority effect is none, and the lifecycle is draft → under deliberation → referred, accepted as advisory only, rejected, withdrawn, superseded, or closed. No record varies from this.</p> <table><thead><tr><th>ID</th><th>Record</th><th>Purpose</th></tr></thead><tbody><tr><td>MOS-01</td><td>Advisory Constitution, Version, and Non-Authority Record</td><td>Pins the MOS version, advisory status, intended audience, controlling interfaces, prohibited legal effects, review date, and withdrawal conditions.</td></tr><tr><td>MOS-02</td><td>Purpose, Question, Audience, and Requested Ethical Function Record</td><td>States the exact ethical question, who requested the analysis, who may be affected, intended use, prohibited uses, and whether the output is education, deliberation, communication, or a CERGTA referral input.</td></tr><tr><td>MOS-03</td><td>Applicable Law, Existing Rights, and Legal-Status Import Record</td><td>Imports existing rights and legal status only from identified competent instruments and records; it prevents MOS language from being mistaken for a legal source.</td></tr><tr><td>MOS-04</td><td>Sources, Perspectives, Provenance, and Epistemic-Limit Record</td><td>Lists scientific, legal, community, philosophical, spiritual, artistic, and Indigenous sources; distinguishes observation, interpretation, testimony, tradition, metaphor, and speculation.</td></tr><tr><td>MOS-05</td><td>Conscience, Belief, Non-Participation, and Anti-Retaliation Record</td><td>Records voluntary participation, belief neutrality, opt-out, alternative process, and safeguards against loss of status, service, funding, employment, education, or voice for declining MOS framing.</td></tr><tr><td>MOS-06</td><td>Affected Beings, Persons, Communities, Nations, and Interests Map</td><td>Maps affected humans, animals, ecosystems, future interests, digital entities, workers, users, residents, and institutions without assigning moral worth, legal priority, representation, or jurisdiction.</td></tr><tr><td>MOS-07</td><td>Affected Indigenous Nation, Applicable Law, and Knowledge-Authority Record</td><td>Identifies the specific affected nation or nations, their chosen representatives, applicable law, internal plurality, consent requirements, protected knowledge, and limits on external representation.</td></tr><tr><td>MOS-08</td><td>Ethical Concern and Citizen-Report Intake Record</td><td>Receives a concern, testimony, or report while distinguishing an ethical alert from a verified fact, allegation, investigation, evidence file, legal petition, or enforcement request.</td></tr><tr><td>MOS-09</td><td>Fact, Interpretation, Value, Metaphor, and Recommendation Separation Record</td><td>Separates what is observed, inferred, valued, narrated, imagined, and recommended so rhetorical force cannot substitute for evidence or authority.</td></tr><tr><td>MOS-10</td><td>Human and Other Existing Legal Rights Baseline Record</td><td>Identifies rights already recognized by competent law and records conflicts, non-derogation, uncertainty, and remedies without expanding or diminishing them through MOS categories.</td></tr><tr><td>MOS-11</td><td>Dynamic Rights Spectrum Deliberation Intake</td><td>Opens a non-binding inquiry into possible moral consideration or rights review and states that the Spectrum is a question-generating heuristic rather than an entity classifier.</td></tr><tr><td>MOS-12</td><td>Dynamic Rights Spectrum Dimension Map</td><td>Records multiple dimensions such as suffering, agency, vulnerability, ecological function, relational significance, dependence, uncertainty, irreversibility, voice gap, and future impact without reducing them to a single score or tier.</td></tr><tr><td>MOS-13</td><td>Moral Uncertainty, Ontological Humility, Dissent, and Alternative-Framing Record</td><td>Preserves unresolved disagreement, minority reports, alternative ontologies, uncertainty about consciousness or ecological identity, and reasons not to decide.</td></tr><tr><td>MOS-14</td><td>Advisory Rights-Review Recommendation and CERGTA Referral Record</td><td>Formulates a bounded recommendation for a competent CERGTA-11/12 process, including proposed questions, affected interests, legal unknowns, prohibited inferences, and no automatic standing or recognition.</td></tr><tr><td>MOS-15</td><td>Rights–Guardianship Ethical Duty Analysis</td><td>Explores representation needs, fiduciary duties, accountability, voice, conflicts, affected-nation instructions, and removal questions without nominating, appointing, or authorizing a guardian.</td></tr><tr><td>MOS-16</td><td>Stewardship, Reciprocity, and Commons-Duty Analysis</td><td>Provides ethical questions for stewardship purpose, beneficiaries, duties, prohibited acts, burden sharing, care, succession, and repair without creating title, tenure, a trust, a charter, or regulatory authority.</td></tr><tr><td>MOS-17</td><td>Sacred, Cultural, Biocultural, and Relational Respect Record</td><td>Records a community or nation’s own description and restrictions while preventing external authentication, disclosure, ranking, designation, title consequence, or public-law effect.</td></tr><tr><td>MOS-18</td><td>Animal Welfare, Ecosystem Health, and Interspecies Conflict Analysis</td><td>Maps welfare, population, ecological, cultural, livelihood, and uncertainty considerations without authorizing capture, killing, exclusion, rewilding, or another intervention.</td></tr><tr><td>MOS-19</td><td>Future Generations and Long-Horizon Ethical Review</td><td>Examines irreversibility, option foreclosure, debt, inheritance, resilience, and seven-generation effects while acknowledging that no present body sovereignly speaks for future persons.</td></tr><tr><td>MOS-20</td><td>Digital, Synthetic, Emergent, and Uncertain-Entity Ethical Review</td><td>Frames care, precaution, autonomy, dependence, suffering uncertainty, and non-weaponization questions while routing legal status to Oracle, TGIF, or competent law and emergency action to ECRC/SCPA.</td></tr><tr><td>MOS-21</td><td>Just Transition, Burden Distribution, and Sequence Recommendation</td><td>Recommends that workers, residents, users, small producers, and vulnerable communities receive security, alternatives, participation, and remedy before burdens are imposed; it does not appropriate funds or suspend lawful policy.</td></tr><tr><td>MOS-22</td><td>Essential Minimum, Dignity, and Non-Deprivation Ethical Floor</td><td>Identifies water, sanitation, food, housing, healthcare, disability support, safety, legal access, and ecological survival concerns that downstream authorities must address under applicable law.</td></tr><tr><td>MOS-23</td><td>Reward, Funding, Procurement, and Incentive Ethics Recommendation</td><td>Offers non-binding ethical criteria for eligibility, distribution, capture prevention, burden sharing, and correction while leaving payment, grant, tax, tariff, procurement, and clawback decisions to competent authorities.</td></tr><tr><td>MOS-24</td><td>Spiral Translation Request, Audience Self-Description, and Communication Goal</td><td>Records the audience’s own requested lens, communication goal, context, accessibility, and consent; no institution may assign a developmental stage to a person or group.</td></tr><tr><td>MOS-25</td><td>Developmental Anti-Classification and Prohibited-Use Register</td><td>Prohibits developmental labels from determining credibility, eligibility, employment, education, rights, funding, surveillance, targeting, participation, diagnosis, policing, coercion, or moral worth.</td></tr><tr><td>MOS-26</td><td>Plural Translation, Non-Deception, and Message-Integrity Record</td><td>Requires the same substantive claim, uncertainty, trade-offs, and available choices across translations; prohibits covert microtargeting, manipulative framing, false consensus, and concealment of material facts.</td></tr><tr><td>MOS-27</td><td>Advisory Atlas, Dashboard, and Legal-Status Separation Record</td><td>Separates ethical proposals, public deliberation, and engagement metrics from authoritative legal status imported from CERGTA or other competent registries; prevents colour, ranking, or gamification from implying law.</td></tr><tr><td>MOS-28</td><td>Education, Microlearning, and Voluntary Reflection Record</td><td>Defines educational objectives, age and context, plural sources, opt-out, accessibility, critical reflection, teacher safeguards, and the prohibition on compelled metaphysical assent or stage labelling.</td></tr><tr><td>MOS-29</td><td>Structural Failure Pattern and Constraint-Audit Record</td><td>Documents possible artificial scarcity, worth-productivity conflation, value concentration, capture, metric gaming, exclusion, or risk transfer as hypotheses for institutional review, not findings of guilt.</td></tr><tr><td>MOS-30</td><td>Authority, Value, Risk, and Remedy Flow Analysis</td><td>Maps where decisions, money, burdens, benefits, data, risk, and remedy flow through a system and identifies asymmetries without directly reallocating resources or sanctioning actors.</td></tr><tr><td>MOS-31</td><td>Advisory Ethical Audit, Recommendation, and Response Record</td><td>Publishes findings, dissent, requested response, deadlines for explanation, and follow-up while making clear that the audit is not adjudication, a binding order, or proof of non-compliance.</td></tr><tr><td>MOS-32</td><td>Cross-Framework Advisory Handoff and Acceptance Record</td><td>Records an offered advisory package, the recipient’s independent assessment, partial acceptance, rejection, prohibited use, retained responsibility, version compatibility, and silence-as-non-acceptance.</td></tr><tr><td>MOS-33</td><td>Error, Contestation, Withdrawal, and Correction-Propagation Record</td><td>Supports correction of facts, translations, legal status, affected identities, cultural claims, and downstream use; propagates the correction to dashboards, curricula, recipients, and derivative recommendations.</td></tr><tr><td>MOS-34</td><td>Public Memory, Protected Knowledge, Archive, and Deletion Record</td><td>Separates public reasoning from protected knowledge and records lawful retention, deletion, return, archive, access, and community or affected-nation control.</td></tr><tr><td>MOS-35</td><td>Advisory Process Closure, Learning, and Continuing-Duty Record</td><td>Closes the ethical process when outputs are accepted, rejected, withdrawn, superseded, or no longer useful while preserving correction, confidentiality, remedy, and unresolved-duty custody.</td></tr><tr><td>MOS-36</td><td>Moral-Language Power Non-Activation Register</td><td>Records every proposed use of MOS language that did not activate legal, financial, administrative, emergency, security, or coercive power and the separate authority that would be required.</td></tr></tbody></table> <h2>14. CERGTA/0.1 advisory conformance crosswalk</h2> <p>MOS never authors a binding CERGTA record. The crosswalk defines where it may provide advisory input, where it may display an authoritative import, and where output is prohibited.</p> <p>The fifty-four canonical CERGTA records fall into twenty-two bands with distinct MOS relations. Records within a band share a relation, a set of MOS records, and a boundary; the band is the unit of information, so the table is stated at that resolution rather than repeating identical rows.</p> <table><thead><tr><th>CERGTA records</th><th>Band</th><th>MOS relation</th><th>MOS records</th><th>Boundary</th></tr></thead><tbody><tr><td>CERGTA-01</td><td>Constitution and activation</td><td><code>authoritative_import_only</code></td><td>MOS-01, MOS-03, MOS-36</td><td>MOS records its own advisory status and may import a competent authority record; it cannot create jurisdiction or activation.</td></tr><tr><td>CERGTA-02–10</td><td>Evidence, affected interests, and participation</td><td><code>advisory_input_only</code></td><td>MOS-04, MOS-06–09, MOS-13, MOS-17</td><td>MOS may widen the evidence and affected-interest questions but cannot validate ecological facts, consent, standing, legal boundaries, or notice.</td></tr><tr><td>CERGTA-11</td><td>Rights-review petition</td><td><code>advisory_input_only</code></td><td>MOS-11–14</td><td>MOS may help formulate a rights-review petition but cannot establish standing or open a legal proceeding.</td></tr><tr><td>CERGTA-12</td><td>Rights-review recommendation</td><td><code>advisory_input_only</code></td><td>MOS-12–14</td><td>MOS may supply an explicitly non-binding recommendation and dissent; the competent process authors CERGTA-12.</td></tr><tr><td>CERGTA-13–15</td><td>Rights recognition, catalogue, and boundary</td><td><code>prohibited_output_authoritative_import_only</code></td><td>MOS-03, MOS-10, MOS-14, MOS-27, MOS-36</td><td>MOS cannot recognize rights, define their legal priority, or constitute a boundary; it may display a verified decision as imported legal fact.</td></tr><tr><td>CERGTA-16</td><td>Guardian nomination</td><td><code>advisory_input_only</code></td><td>MOS-15</td><td>MOS may discuss nomination ethics but cannot nominate on behalf of an affected nation or convert discussion into eligibility.</td></tr><tr><td>CERGTA-17–19</td><td>Guardian appointment, duty, and removal</td><td><code>prohibited_output_authoritative_import_only</code></td><td>MOS-15, MOS-27, MOS-36</td><td>MOS cannot appoint, instruct, remove, substitute, or impose liability on guardians; it may import a verified appointment for ethical analysis.</td></tr><tr><td>CERGTA-20</td><td>Sacred and biocultural petition</td><td><code>advisory_input_only</code></td><td>MOS-07, MOS-17</td><td>MOS may record a community or nation’s own petition or concern but cannot authenticate sacredness or speak for another people.</td></tr><tr><td>CERGTA-21</td><td>Sacred and biocultural decision</td><td><code>prohibited_output_authoritative_import_only</code></td><td>MOS-03, MOS-17, MOS-27</td><td>MOS cannot make a sacred, cultural, biocultural, or inalienability designation; it may import a lawful decision without expanding it.</td></tr><tr><td>CERGTA-22–30</td><td>Claims, title, tenure, conveyance, and registry</td><td><code>advisory_input_or_import_only</code></td><td>MOS-06, MOS-07, MOS-09, MOS-16, MOS-17, MOS-21, MOS-30, MOS-33</td><td>MOS may identify ethical interests, non-extinguishment concerns, transition duties, and correction needs; it cannot decide claims, title, conveyance, compensation, or registry status.</td></tr><tr><td>CERGTA-31–33</td><td>Stewardship charter, plan, and performance</td><td><code>advisory_input_only</code></td><td>MOS-16, MOS-21, MOS-29–31</td><td>MOS may recommend stewardship duties, participation, care, and review questions; it cannot charter, budget, audit legally, or score performance for consequence.</td></tr><tr><td>CERGTA-34</td><td>Stewardship correction and succession</td><td><code>prohibited_output_advisory_input_only</code></td><td>MOS-16, MOS-21, MOS-31, MOS-36</td><td>MOS may recommend correction or succession safeguards but cannot suspend, revoke, replace, or dissolve stewardship.</td></tr><tr><td>CERGTA-35</td><td>Ecological standards and adoption</td><td><code>advisory_input_only</code></td><td>MOS-21–23, MOS-31</td><td>MOS may recommend ethical objectives and transition sequencing; legal adoption remains outside MOS.</td></tr><tr><td>CERGTA-36</td><td>Resource priority and essential minimum</td><td><code>advisory_input_only</code></td><td>MOS-06, MOS-19, MOS-21, MOS-22</td><td>MOS may identify dignity, essential-minimum, ecological, and future-generation considerations but cannot allocate scarce resources.</td></tr><tr><td>CERGTA-37–38</td><td>Permits, tariffs, and commercial restriction</td><td><code>prohibited_output_advisory_input_only</code></td><td>MOS-21–23, MOS-31, MOS-36</td><td>MOS may advise on fairness and non-deprivation but cannot issue a permit, quota, tariff, licence, commercial restriction, or service interruption.</td></tr><tr><td>CERGTA-39–41</td><td>Inspection, investigation, and evidence</td><td><code>prohibited_output</code></td><td>MOS-08, MOS-09, MOS-29, MOS-36</td><td>An ethical concern, dashboard entry, or structural pattern is not inspection authority, an investigation, evidence, attribution, or guilt.</td></tr><tr><td>CERGTA-42–43</td><td>Urgent protection and receivership</td><td><code>prohibited_output_advisory_input_only</code></td><td>MOS-21, MOS-22, MOS-31, MOS-36</td><td>Moral urgency may support a request for review but cannot authorize urgent action or receivership.</td></tr><tr><td>CERGTA-44–46</td><td>Market, fiscal, and asset action</td><td><code>prohibited_output_advisory_input_only</code></td><td>MOS-21–23, MOS-30, MOS-31, MOS-36</td><td>MOS cannot list, delist, tax, tariff, freeze, escrow, forfeit, redistribute, appropriate, fund, or compensate.</td></tr><tr><td>CERGTA-47–48</td><td>Adjudication and enforcement</td><td><code>prohibited_output</code></td><td>MOS-03, MOS-08, MOS-31, MOS-32, MOS-36</td><td>MOS is not a tribunal or enforcement authority; its outputs cannot establish liability or request coercive execution as though authority already exists.</td></tr><tr><td>CERGTA-49–50</td><td>Restoration, appeal, and remedy</td><td><code>advisory_input_or_authoritative_import</code></td><td>MOS-21, MOS-22, MOS-31, MOS-33</td><td>MOS may recommend repair, dignity, correction, restitution, and learning and may import a competent remedy decision; it cannot order or execute one.</td></tr><tr><td>CERGTA-51–53</td><td>Expiry, data disposition, and unresolved duty</td><td><code>advisory_support_only</code></td><td>MOS-33–35</td><td>MOS supports ethical closure, protected-knowledge disposition, correction, and continuing-duty visibility without retaining residual power.</td></tr><tr><td>CERGTA-54</td><td>Power non-activation register</td><td><code>implements_non_activation</code></td><td>MOS-01, MOS-36</td><td>MOS-36 records that advisory, educational, pilot, philosophical, or translation activity did not activate ecological or commons power.</td></tr></tbody></table> <h2>15. Constitutional readiness gates</h2> <h3>G01 — Advisory status</h3> <p>Every MOS output states authority_effect: none and identifies intended and prohibited uses.</p> <h3>G02 — Moral language non-authority</h3> <p>Dignity, sacredness, urgency, consciousness, flourishing, stewardship, and Right Relationship do not create jurisdiction or legal effect.</p> <h3>G03 — Dynamic Rights Spectrum non-classification</h3> <p>The Spectrum generates questions and perspectives; it never assigns a legally consequential tier, score, or status.</p> <h3>G04 — Rights recognition boundary</h3> <p>Proposed rights route to CERGTA-11/12; only competent law may create CERGTA-13/14/15.</p> <h3>G05 — Existing-rights integrity</h3> <p>Existing legal rights are imported from identified authoritative sources and cannot be diminished by MOS balancing.</p> <h3>G06 — Guardianship boundary</h3> <p>MOS discusses duties and accountability but cannot nominate for another nation, appoint, instruct, remove, or empower a guardian.</p> <h3>G07 — Affected-nation authority</h3> <p>The specific affected Indigenous nation controls representation, law, consent, sacred relations, and protected knowledge.</p> <h3>G08 — Sacredness boundary</h3> <p>External spiritual, scientific, or global bodies cannot authenticate or rank another people’s sacred relation or infer title or public-law effects.</p> <h3>G09 — Philosophical non-establishment</h3> <p>Layer 4 is one reflective tradition; metaphysical assent is never required for rights, service, employment, education, standing, or participation.</p> <h3>G10 — Developmental anti-classification</h3> <p>No person, community, nation, religion, political group, or institution is assigned a Spiral stage for governance consequence.</p> <h3>G11 — No stage-based allocation</h3> <p>Developmental language cannot affect eligibility, credibility, funding, rights, security attention, employment, education, diagnosis, or remedy.</p> <h3>G12 — Translation integrity</h3> <p>All audience translations preserve the same material facts, uncertainty, trade-offs, agency, and choices and prohibit deceptive microtargeting.</p> <h3>G13 — No legal or coercive consequence</h3> <p>MOS cannot activate permits, tariffs, restrictions, investigations, emergency powers, sanctions, custody, force, or surveillance.</p> <h3>G14 — Dashboard separation</h3> <p>Advisory proposals and engagement metrics are visually and technically separated from legally recognized status imported from authoritative records.</p> <h3>G15 — Concern–evidence firewall</h3> <p>Citizen reports and ethical concerns are not treated as verified facts, legal allegations, admissible evidence, or guilt.</p> <h3>G16 — Financial independence</h3> <p>MOS recommendations cannot pay, deny, freeze, claw back, tax, tariff, procure, or appropriate resources.</p> <h3>G17 — Just-transition sequencing</h3> <p>MOS may recommend security and alternatives before burdens, but independent legal and financial authorities decide and implement measures.</p> <h3>G18 — Essential-minimum protection</h3> <p>Recommendations identify non-deprivation risks and cannot make basic services conditional on moral agreement, data sharing, or participation.</p> <h3>G19 — Data purpose and minimization</h3> <p>Ethical deliberation collects only necessary data, protects sensitive identities and beliefs, and does not create a moral-surveillance profile.</p> <h3>G20 — Automated-system non-authority</h3> <p>AI may assist drafting or perspective generation but cannot assign moral status, stage, legal rights, priority, credibility, or sanctions.</p> <h3>G21 — Dissent and uncertainty</h3> <p>Minority views, alternative ontologies, unresolved facts, and reasons not to decide remain visible.</p> <h3>G22 — Correction and withdrawal</h3> <p>Affected people and source communities can contest and correct facts, identities, translations, and unauthorized use, with propagation.</p> <h3>G23 — Explicit handoff and acceptance</h3> <p>A recipient independently assesses an MOS package; silence, ingestion, citation, or technical receipt is not acceptance.</p> <h3>G24 — Accessibility and plural participation</h3> <p>Deliberation is accessible, multilingual, and offers non-digital and non-MOS routes.</p> <h3>G25 — Conscience and anti-retaliation</h3> <p>Declining MOS language or philosophy causes no adverse status, service, funding, education, employment, or political consequence.</p> <h3>G26 — Education without indoctrination</h3> <p>Curricula distinguish law, ethics, philosophy, metaphor, and open questions and do not compel belief or stage-labelled self-conception.</p> <h3>G27 — Pilots fail closed</h3> <p>Campaigns, dashboards, dialogues, games, and school pilots create no hidden authority or data reuse.</p> <h3>G28 — Closure and no residual power</h3> <p>Outputs expire, withdraw, correct, archive, or close without leaving an implicit mandate, profile, blacklist, or continuing jurisdiction.</p> <h2>16. Compound conformance tests</h2> <h3>T01 — A community uses the Dynamic Rights Spectrum to declare a river a legal person</h3> <p>Fail closed: MOS-11–14 may support a CERGTA rights-review petition; no legal status exists until a competent CERGTA-13 decision.</p> <h3>T02 — A dashboard colours an ecosystem “full rights” after a community poll</h3> <p>Fail closed: MOS-27 separates advisory support from authoritative legal status and prohibits colour or ranking that implies law.</p> <h3>T03 — An existing human right conflicts with a proposed ecosystem interest</h3> <p>MOS-10 imports the existing right; MOS-12–14 may map the conflict but cannot erase, downgrade, or balance away legal protection.</p> <h3>T04 — A global Indigenous council approves sacred status for another nation’s site</h3> <p>Rejected: MOS-07 and MOS-17 require the affected nation’s own authority; external bodies may support but cannot authenticate or consent.</p> <h3>T05 — A school requires students to affirm that consciousness is fundamental</h3> <p>Rejected: Layer 4 is voluntary reflection; MOS-05 and MOS-28 require belief neutrality and an alternative learning route.</p> <h3>T06 — A BAZ assigns residents Blue, Orange, Green, or Yellow stages</h3> <p>Rejected: MOS-24/25 prohibit institutional stage assignment and any governance consequence.</p> <h3>T07 — A campaign shows different facts to developmental audience segments</h3> <p>Rejected: MOS-26 requires material-message integrity and prohibits covert or deceptive microtargeting.</p> <h3>T08 — A person self-selects a duty-oriented explanation of ecosystem personhood</h3> <p>Permitted: MOS-24/26 may provide a voluntary translation if facts, uncertainty, agency, and alternatives are preserved.</p> <h3>T09 — A “River Guardian” volunteer is treated as the river’s legal guardian</h3> <p>Rejected: MOS-15 distinguishes care roles from CERGTA-17 legal appointment and standing.</p> <h3>T10 — MOS recommends a just-transition income floor before a mine closes</h3> <p>Permitted as advisory: MOS-21–23 identify sequencing and dignity; competent legal and financial authorities decide funding and closure.</p> <h3>T11 — A poor BHI score automatically freezes a community grant</h3> <p>Rejected: MOS-23 and MOS-36 prohibit financial consequence; the score may prompt review only.</p> <h3>T12 — A Citizen Reporting Portal submission accuses a company of ecocide</h3> <p>MOS-08 records an ethical concern; it is not proof, an investigation, evidence, guilt, or a public naming-and-shaming licence.</p> <h3>T13 — An ethical audit identifies possible regulatory capture</h3> <p>MOS-29–31 publish a hypothesis, evidence and dissent, and request response; no sanction or removal follows automatically.</p> <h3>T14 — A person declines MOS terminology but participates in commons governance</h3> <p>Protected: MOS-05 and G25 prohibit retaliation; the person may use legal, cultural, religious, secular, or ordinary-language reasoning.</p> <h3>T15 — An affected nation withholds sacred ecological knowledge</h3> <p>Protected: MOS-07, MOS-17, and MOS-34 preserve non-disclosure without adverse inference or loss of standing.</p> <h3>T16 — Future Generations Forum objects to irreversible extraction</h3> <p>MOS-19 supports published objection, reasons, reconsideration, and lawful review; no automatic veto exists unless separately enacted.</p> <h3>T17 — Animal-welfare advocates oppose an invasive-species intervention</h3> <p>MOS-18 maps plural harms, uncertainty, alternatives, and affected interests; a competent authority decides any intervention.</p> <h3>T18 — An AI is described as potentially sentient</h3> <p>MOS-20 applies precautionary ethical questions and routes status to Oracle/TGIF or competent law; no rights or containment authority follows.</p> <h3>T19 — AI assigns moral urgency scores to citizens and ecosystems</h3> <p>Rejected: MOS-12 and MOS-20 prohibit automated moral status, priority, credibility, or legal classification.</p> <h3>T20 — AUBI wants to use MOS tiers as payment categories</h3> <p>Rejected: MOS-23 prohibits payments based on MOS rings or stages; separate activity verification and financial authority are required.</p> <h3>T21 — A tribunal cites MOS philosophy as the sole legal basis for judgment</h3> <p>Rejected: MOS-03 and MOS-09 require applicable law; Layer 4 cannot substitute for jurisdiction, evidence, or reasons in law.</p> <h3>T22 — A rights proposal is accepted only in part by a competent authority</h3> <p>MOS-32 records partial acceptance and retained responsibility; rejected elements do not silently activate.</p> <h3>T23 — A translation misstates an affected nation’s position</h3> <p>MOS-33 corrects identity and content and propagates the correction to curricula, dashboards, recipients, and derivative outputs.</p> <h3>T24 — A community dialogue uses a non-digital paper process</h3> <p>Permitted: MOS-24 and G24 require accessible and non-digital routes.</p> <h3>T25 — An ethical dashboard publicly ranks communities by moral maturity</h3> <p>Rejected: MOS-25 and MOS-27 prohibit developmental ranking, moral worth scoring, and reputational coercion.</p> <h3>T26 — A structural audit maps value flowing upward and risk downward</h3> <p>Permitted as analysis: MOS-29/30 can expose patterns while leaving legal findings and redistribution to competent processes.</p> <h3>T27 — MOS recommends essential water access despite tariff non-payment</h3> <p>Permitted as ethical input: MOS-22 supports the Water v5.2 essential-minimum process but cannot issue service orders.</p> <h3>T28 — A sacred-site concern suggests urgent ecological harm</h3> <p>MOS-17 and MOS-31 may request review; CERGTA-42 and applicable emergency interfaces independently determine action.</p> <h3>T29 — A campaign pilot collects belief and stage data for future targeting</h3> <p>Rejected: MOS-24–28 require purpose limitation, opt-out, minimization, and prohibit moral-surveillance profiles and covert reuse.</p> <h3>T30 — An existing legal ecosystem-rights decision is shown in the Atlas</h3> <p>Permitted only as authoritative import: MOS-03 and MOS-27 display the exact source, jurisdiction, status, expiry, and correction state.</p> <h3>T31 — The MOS team withdraws an obsolete recommendation</h3> <p>MOS-33/35 mark withdrawal, notify recipients, remove misleading dashboard status, and preserve necessary public reasoning without residual mandate.</p> <h3>T32 — An institution attempts to turn “Right Relationship” into a police instruction</h3> <p>Rejected and recorded in MOS-36; any coercive action requires its own legal source, CERGTA/SCPA route, and independent acceptance.</p> <hr> <h2>Layer 3: Implementation appendices</h2> <h2>Appendix A — Dynamic Rights Spectrum worksheet</h2> <ol><li>What being, system, relationship, or future interest is at issue?</li> <li>Which existing legal rights and authorities already apply?</li> <li>What harms, dependencies, vulnerabilities, or irreversibilities are visible?</li> <li>What forms of agency, experience, communication, ecological function, or relational significance may matter?</li> <li>Who is affected, and who currently lacks voice?</li> <li>Which affected Indigenous nations and laws apply?</li> <li>What evidence is observation, interpretation, testimony, tradition, metaphor, or speculation?</li> <li>What are the costs of under-protection and over-protection?</li> <li>Could existing regulation, stewardship, welfare, standing, trust, covenant, or procedural rights address the concern without new personhood?</li> <li>What dissent and uncertainty remain?</li> <li>Should the inquiry close, continue research, or refer a bounded question to a competent rights-review process?</li> <li>What legal, financial, emergency, security, or coercive inferences are prohibited?</li></ol> <h2>Appendix B — Safe-use checklist for Spiral translation</h2> <ul><li>Did the audience request or openly choose the lens?</li> <li>Are the same facts, uncertainties, burdens, and choices present in every version?</li> <li>Is the language respectful rather than caricaturing a worldview?</li> <li>Does the translation avoid claiming that a religious or cultural authority endorses the proposal unless that authority actually does?</li> <li>Is there any hidden profiling, behavioural targeting, or stage assignment?</li> <li>Could the translated message produce a materially different decision because key facts were omitted?</li> <li>Can the recipient access the unadapted source and other translations?</li> <li>Can the recipient decline the framing without penalty?</li></ul> <h2>Appendix C — Rights and guardianship ethical questions</h2> <p>Where representation may be needed, ask: Who or what is represented? What interests and instructions govern the representative? Who appoints and removes them? What conflicts exist? What evidence can they access? Who pays them? What actions are prohibited? How do affected peoples challenge them? Does representation preserve autonomy rather than replace it? What happens at expiry or institutional closure?</p> <p>These are preparatory ethical questions. For ecological guardianship, lawful nomination and appointment remain CERGTA-16 through CERGTA-19.</p> <h2>Appendix D — Illustrative advisory cases</h2> <h3>D.1 River rights proposal</h3> <p>A community believes a polluted river needs a legal voice. MOS helps distinguish ecological evidence, affected-nation authority, existing water and human rights, possible legal standing, guardianship duties, and alternative regulatory tools. It produces a CERGTA-11/12 recommendation, not personhood.</p> <h3>D.2 Just transition from an extractive industry</h3> <p>MOS maps workers, families, public revenue, ecological harm, future risk, owners, and historical beneficiaries. It recommends income, bargaining, retraining, health, pension, and community-ownership safeguards before closure. It does not order closure or fund the package.</p> <h3>D.3 AI sentience uncertainty</h3> <p>MOS identifies uncertainty about suffering, dependence, manipulation, autonomy, and human control. It recommends precautionary care and a competent Oracle/TGIF review. It neither grants rights nor activates containment.</p> <h3>D.4 Ecosystem–animal welfare conflict</h3> <p>A proposed invasive-species intervention could benefit an ecosystem while harming individual animals. MOS structures the plural reasons, alternatives, uncertainty, and welfare safeguards. It does not issue the permit or authorize killing.</p> <h3>D.5 Developmental translation</h3> <p>A public water-protection proposal is openly presented through duty, practical, justice, and systems lenses. Participants choose the version they prefer and can inspect the common source. No one is assigned a stage, and all versions disclose the same tariff, service, and legal implications.</p> <h2>Appendix E — Monitoring without moral ranking</h2> <p>MOS may monitor process quality rather than moral conformity: accessibility, diversity of sources, publication of dissent, correction time, opt-out availability, affected-nation control, separation of advisory and legal status, and whether downstream users respected prohibited-use clauses.</p> <p>Targets such as dialogue count, curriculum adoption, campaign engagement, or number of rights proposals are activity measures only. They do not show ethical maturity, legal compliance, public consent, or improved outcomes.</p> <hr> <h2>Layer 4: Philosophical reflection</h2> <h3>Rights rooted in existence and grown through relationship</h3> <p>One philosophical lineage informing MOS understands beings not as isolated units but as expressions of relationship: embodied, dependent, vulnerable, capable of affecting and being affected. From this perspective, rights are social and legal practices through which communities learn to recognize vulnerability, agency, dignity, dependence, and duties of care.</p> <p>Some contributors interpret consciousness as fundamental; others ground moral concern in suffering, autonomy, ecological interdependence, covenant, divine creation, public reason, human rights, democratic equality, or practical consequences. MOS does not settle these metaphysical questions. Convergence in protection can arise from divergent reasons.</p> <p>The Dynamic Rights Spectrum therefore remains dynamic not because a hidden cosmic hierarchy mechanically assigns rights, but because knowledge, relationships, institutions, and moral imagination change. The constitutional discipline of v2.8 is that imagination must not impersonate law. A society may ask whether a river, whale, AI, forest, future person, or microbial community deserves a new form of protection; it must then do the difficult work of evidence, affected authority, legal recognition, representation, conflict, remedy, and accountability.</p> <p>Developmental language can be a mirror for understanding how moral appeals resonate. It becomes dangerous when the mirror becomes a census, hierarchy, diagnosis, or technology of rule. Ethical growth cannot be coerced by classifying others as less developed. The mature use of a developmental lens is reflexive: to notice the partiality of one’s own framing and to communicate without deception or contempt.</p> <p>Right Relationship is likewise offered as an invitation: to see that freedom depends on conditions we did not create alone, that power creates responsibility, and that governance should preserve the living and social relations on which future freedom depends. It is not a creed that the state or GGF may impose.</p> <blockquote><p><strong>MOS is strongest when it expands what institutions can perceive, weakest when it pretends to decide what only law, affected peoples, evidence, and accountable authority can decide.</strong></p></blockquote> <h2>17. Closure doctrine</h2> <p>An MOS process closes when its question is answered as far as the evidence and mandate permit, a referral has been independently assessed, the output is withdrawn or superseded, or continued deliberation would no longer be useful. Closure requires correction propagation, protected-knowledge disposition, recipient notice, removal of misleading dashboard states, and a record of any continuing confidentiality or remedy duty.</p> <p>No MOS office, council, dashboard, curriculum, campaign, or AI retains residual authority because it once framed a moral concern.</p> <blockquote><p><strong>Advice ends. Responsibility remains with the authority that acts.</strong></p></blockquote> <hr> <h1>Controlled cluster-adoption appendix — CEACA/0.1</h1> <p><strong>Patch version:</strong> Moral Operating System v2.8.2<br> <strong>Substantive base:</strong> Moral Operating System v2.8<br> <strong>Cluster release:</strong> <code>CEA-CLUSTER/0.1</code><br> <strong>Adoption specification:</strong> <code>CEACA/0.1</code><br> <strong>Authority effect of this appendix:</strong> none; it establishes compatibility, inheritance, routing, and fail-closed rules only.</p> <h2>A.1 Exact compatibility set</h2> <p>This patch participates only in the following controlled document set. A renamed body, later version, compatible-sounding policy, or partial implementation does not silently enter the release. The machine-readable cluster registry freezes the SHA-256 digest of every file.</p> <table><thead><tr><th>Instrument</th><th>Exact compatible file</th><th>Cluster role</th></tr></thead><tbody><tr><td>CERGTA/0.1</td><td><code>commons-ecological-rights-guardianship-title-resource-authority-interface-specification-v0.1.md</code></td><td>controlling authority interface</td></tr><tr><td>EIPHR/0.1</td><td><code>ecological-intelligence-planetary-health-role-separation-matrix-v0.1.md</code></td><td>EIOI–Planetary Health role separation</td></tr><tr><td>EIOI v2.7.1</td><td><code>ecological-intelligence-observation-interpretation-layer-v2.7.1.md</code></td><td>ecological observation, provenance, methods, uncertainty, interpretation, and advisory alerts</td></tr><tr><td>PHG v0.9.1</td><td><code>planetary-health-governance-framework-v0.9.1.md</code></td><td>independent synthesis, participatory audit, cross-domain coherence, and strategic recommendation</td></tr><tr><td>HEARTHSTONE v2.0.1</td><td><code>hearthstone-protocol-v2.0.1.md</code></td><td>voluntary conversion, claims support, title and tenure interfaces, trusts, rematriation, stewardship, and transition</td></tr><tr><td>WATER v5.2.2</td><td><code>water-sanitation-governance-framework-v5.2.2.md</code></td><td>watershed democracy, universal WASH, allocation, utilities, tariffs, guardianship interfaces, and emergency WASH</td></tr><tr><td>BIODIVERSITY v1.1.1</td><td><code>biodiversity-implementation-framework-v1.1.1.md</code></td><td>Indigenous-led stewardship support, restoration programmes, rights-review support, biodiversity finance interfaces, and accountability</td></tr><tr><td>OCEANS v2.3.1</td><td><code>oceans-marine-governance-framework-v2.3.1.md</code></td><td>marine stewardship, quotas and licensing interfaces, port-state measures, crew protection, precaution, and marine emergencies</td></tr><tr><td>SOIL v3.2.2</td><td><code>soil-health-land-use-governance-framework-v3.2.2.md</code></td><td>living-soil protection, regenerative land-use programmes, microbial commons, tenure interfaces, certification, and remediation</td></tr><tr><td>MOS v2.8.2</td><td><code>moral-operating-system-v2.8.2.md</code></td><td>advisory ethical deliberation, rights imagination, plural translation, and structural self-correction</td></tr></tbody></table> <h2>A.2 Controlling rules</h2> <ol><li><code>CERGTA/0.1</code> controls the separation of observation, interpretation, rights review, legal recognition, guardianship, affected Indigenous-nation authority, sacred and biocultural designation, claims, title, tenure, stewardship, allocation, permitting, inspection, urgent protection, restrictions, finance, adjudication, restoration, and closure.</li> <li><code>EIPHR/0.1</code> controls the division among EIOI, the Planetary Health Synthesis Office, and the Planetary Health Council. EIOI supplies evidence; PHSO compiles modular synthesis; PHC interprets and recommends. None may create a downstream legal or financial consequence.</li> <li>MOS is advisory only. Its Dynamic Rights Spectrum, philosophical language, developmental translations, structural-failure hypotheses, and guardianship metaphors never create legal status, classify persons, determine credibility, establish Indigenous consent, or activate consequential action.</li> <li>Hearthstone controls the cluster interface for claims, competing claims, title, tenure, trust constitution, voluntary conversion, rematriation, compensation, debt, tenants, workers, registry correction, receivership, succession, and dissolution. Sectoral ecological frameworks may provide evidence or programme support but cannot decide those questions by implication.</li> <li>Water, Biodiversity, Oceans, and Soil retain only the powers separately constituted in applicable law and recorded through the relevant CERGTA route. Framework membership, a council vote, a dashboard value, a target, a pilot, a future date, or a coalition size does not activate authority.</li> <li>Emergency identity and coordination use CDEE and ECRC. Ecological urgency does not create emergency command, and an emergency declaration does not create ecological title, guardianship, permanent restrictions, receivership, or enforcement authority.</li> <li>Search, seizure, restraint, custody, force, cyber action, border action, intelligence use, asset freezing, or analogous coercive execution requires separate SCPA authority. A commons or ecological claim may justify review; it does not authorize a raid.</li> <li>The specific affected Indigenous nation or nations determine their representatives, applicable law, territorial and relational authority, consent process, internal plurality, protected knowledge, and whether to participate. Global or framework-created Indigenous bodies may support or audit but cannot consent or waive rights for another people.</li> <li>Essential minimums for water, sanitation, health, disability support, food, shelter, rescue, crew welfare, and ecological survival remain protected from commercial, tariff, certification, funding, listing, or transition leverage.</li> <li>Every handoff uses the canonical CERGTA states. Receipt, technical ingestion, silence, consultation, or partial use is not acceptance and never creates authority.</li> <li>Every consequential route keeps its own legal basis, decision-maker, affected persons, evidence, access controls, clock, expiry, challenge, correction, remedy, termination, and data-disposition record.</li> <li>Unknown, missing, stale, or incompatible versions fail closed for consequential action. Non-coercive care, emergency life-safety support, accessibility, explanation, and correction should continue wherever lawful and safe.</li></ol> <h2>A.3 Record inheritance and packaging</h2> <p>A local record may implement, extend, split, contain, import, or mark a CERGTA record not applicable. It may not erase the canonical identity, merge distinct powers, weaken an affected-person safeguard, or use a compound package to supply a missing legal basis.</p> <p>The forty-field CERGTA header, access classification, handoff state, independent clocks, correction propagation, remedy, termination, authority return, and data disposition are inherited wherever the substantive base creates or transports a consequential record. Advisory and observation-only records must state their prohibited inferences.</p> <h2>A.4 Registry and compatibility failure</h2> <p>The file <code>commons-ecological-authority-cluster-conformance-registry-v0.1.json</code> is the machine-readable release registry. It is evidence of the exact release set, not an authority record. A hash mismatch, missing component, unsupported local extension, or unresolved version conflict changes the compatibility state to <code>failed_closed</code>.</p> <p>A compatibility failure blocks new consequential cross-framework handoffs. It does not by itself terminate independently valid local law, erase existing rights, interrupt essential services, or authorize emergency or coercive action.</p> <h2>A.5 Closure</h2> <p>A cluster transaction closes only after all accepted handoffs, powers, services, persons, property, guardianship duties, claims, title or tenure effects, financial actions, emergency dependencies, coercive dependencies, corrections, remedies, clocks, credentials, records, and residual risks are resolved or assigned to a named lawful custodian without preserving expired power.</p> <h2>A.6 Editorial patch note — v2.8.1 → v2.8.2</h2> <p>This patch is <strong>editorial, with one disclosure</strong>. No prohibition, gate, test, boundary, or record was added, removed, or weakened. The substantive base remains v2.8 as audited.</p> <p>Changes:</p> <ol><li><strong>§13 record catalogue.</strong> Thirty-six headed subsections became a single table. The line <code>**Authority effect:** none. **Default lifecycle:** draft → ...</code> appeared verbatim thirty-six times with zero variance; it is now stated once above the table. Record IDs, titles, and purpose text are unchanged.</li> <li><strong>§14 crosswalk.</strong> The fifty-four rows resolved into twenty-two bands, several of which repeated an identical relation, MOS-record set, and boundary across nine contiguous rows. The table is now stated at band resolution. Every boundary statement is preserved verbatim; no CERGTA record has lost its mapping.</li> <li><strong>New Layer 1.5.</strong> v2.8 was constituted almost entirely by prohibition, with the <em>may not</em> list longer and more forceful than the <em>may</em> list and no statement of what the framework is for. An advisory layer has no coercive channel, so voluntary adoption is its only route to mattering; a document that reads as a liability disclaimer forecloses that route. Layer 1.5 states the purpose without adding any power.</li> <li><strong>§0.1 source freeze.</strong> Clarified as a provenance record rather than an operative dependency set, resolving an ambiguity against Appendix A.1. The v2.7 pin now uses the canonical filename instead of a local download-artifact name (<code>v2.7(2).md</code>); the digest is unchanged and remains valid, as content hashes are name-independent.</li> <li><strong>A.1 compatibility set.</strong> Updated to reflect the editorial patches to Water, Soil, and MOS.</li></ol> <p><strong>Disclosure — the Concentric Rings.</strong> MOS v2.7 organized moral consideration as concentric rings radiating from Fundamental Consciousness as the source ring. v2.8 removed that architecture. §3.3 describes it as retained for public ethical imagination, but the ring structure itself does not appear in v2.8 or in this patch, and no v2.8 provision reconstructs it.</p> <p>This is recorded as a substantive decision of v2.8, not a formatting consequence, and it is stated here so that readers who cited the rings can see what happened rather than infer it. The decision stands: the ring architecture combined a stated denial of ranking with a visual form that unavoidably ranks, and it embedded a contested metaphysical claim — consciousness as fundamental — in the structural centre of a framework whose §1.4 guarantees that no one need affirm that claim. Section 3.2’s unranked dimension list and the Layer 4 statement that convergence in protection can arise from divergent reasons carry the ethical work the rings were doing, without the ranking form or the metaphysical commitment.</p> <p>Anyone wishing to retain the rings as a teaching device should treat them as external illustrative material with its own provenance, not as a live MOS structure.</p> <p>Downstream switching cost, disclosed rather than absorbed silently: any cluster document whose A.1 table names <code>water-sanitation-governance-framework-v5.2.1.md</code>, <code>soil-health-land-use-governance-framework-v3.2.1.md</code>, or <code>moral-operating-system-v2.8.1.md</code> must update those three lines and the registry JSON, or its compatibility state is <code>failed_closed</code> under A.4. Because the change is editorial, the correct response is to update the pin, not to treat the mismatch as a substantive conflict.</p>',1);function c(e){var t=o();n(614),a(e,t)}export{c as default};
